mapper.select:
select t.machine_mac,t.machine_mac machineMac,t.heartbeat_time,t.heartbeat_time
heartbeatTime,t.impl_bean,t.impl_bean implBean,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.location_name,t.location_name locationName,t.location_id,t.location_id
locationId,t.status_cd,t.status_cd statusCd,t.create_time createTime,t.community_id,t.community_id
communityId,t.machine_name,t.machine_name machineName,t.machine_ip,t.machine_ip machineIp,t.direction,hm.hm_name
implBeanName,t.prompt_switch promptSwitch,t.normal_prompt normalPrompt,t.owe_prompt owePrompt,hm.protocol_impl protocolImpl,
t.monitor_id monitorId,t.monitor_name monitorName,t.platform_id platformId,cp.platform_name platformName,t.calling_num callingNum
from access_control t
left join hardware_manufacturer hm on t.impl_bean = hm.hm_id and hm.status_cd = '0'
left join calling_platform cp on t.platform_id = cp.platform_id and cp.status_cd = '0'
where 1 =1


    and t.machine_mac= #{machineMac}


    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.location_name= #{locationName}


    and t.location_id= #{locationId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.platform_id= #{platformId}


    and t.calling_num= #{callingNum}


    and t.prompt_switch= #{promptSwitch}


    and t.normal_prompt= #{normalPrompt}


    and t.owe_prompt= #{owePrompt}

order by t.create_time desc

    limit #{page}, #{row}

