mapper.select:
select count(1) count
from access_control t
where 1 =1

    and t.machine_mac= #{machineMac}


    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.location_name= #{locationName}


    and t.location_id= #{locationId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.prompt_switch= #{promptSwitch}


    and t.normal_prompt= #{normalPrompt}


    and t.platform_id= #{platformId}


    and t.calling_num= #{callingNum}


    and t.owe_prompt= #{owePrompt}


    and t.monitor_id= #{monitorId}


    and t.monitor_name= #{monitorName}

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from access_control_inout t
WHERE 1=1

    and t.machine_id= #{machineId}


    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from access_control_log t
WHERE 1=1

    and t.machine_id= #{machineId}


    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from visit t
WHERE 1=1

    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from person_face t
WHERE 1=1

    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select count(1) count
from ( select t.machine_id
from access_control t
left join access_control_face acf on t.machine_id = acf.machine_id and acf.status_cd = '0'
where 1=1
and acf.person_type = #{personType}
and acf.person_id = #{personId}

    and t.machine_mac= #{machineMac}


    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.location_name= #{locationName}


    and t.location_id= #{locationId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.monitor_id= #{monitorId}


    and t.monitor_name= #{monitorName}

group by t.machine_id
) a

select distinct t.machine_mac machineMac,t.heartbeat_time
heartbeatTime,t.impl_bean implBean,t.machine_id machineId,t.machine_code
machineCode,t.location_name locationName,t.location_id
locationId,t.status_cd statusCd,t.create_time createTime,t.community_id
communityId,t.machine_name machineName,t.machine_ip machineIp,t.direction,
t.prompt_switch promptSwitch,t.normal_prompt normalPrompt,t.owe_prompt owePrompt,
t.monitor_id monitorId,t.monitor_name monitorName
from access_control t
left join access_control_face acf on t.machine_id = acf.machine_id and acf.status_cd = '0'
where 1=1
and acf.person_type = #{personType}
and acf.person_id = #{personId}

    and t.machine_mac= #{machineMac}


    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.location_name= #{locationName}


    and t.location_id= #{locationId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.monitor_id= #{monitorId}


    and t.monitor_name= #{monitorName}

order by t.create_time desc

    limit #{page}, #{row}
